    def play(self, file_name, start, loops=0):
        self.music = self.Music(file_name)
        self.slider.SetMin(0)
        self.slider.SetMax(int(self.music.length))
        self.music.start(loops=loops, start=start)
        self.slide_count = start
        self.play_flag = True
        self.pause_flag = False

    def thread_work(self):
        while True:
            if self.destroy_flag:
                break
            time.sleep(self.COUNT_VALUE)
            if not hasattr(self, "music") or not self.play_flag:
                continue
            self.slider.SetValue(int(self.slide_count))

            max_count = 0
            if self.button_rep_start_toggle.GetValue():
                max_count = int(self.text_ctrl_rep_end.GetValue())
            else:
                max_count = self.music.length

            if self.play_flag and not self.pause_flag:
                if self.slide_count <= max_count:
                    self.slide_count += self.COUNT_VALUE
                else:
                    if self.button_rep_start_toggle.GetValue():
                        self.slide_count = int(self.text_ctrl_rep_start.GetValue())
                        self.music.start(loops=0, start=self.slide_count)
                    else:
                        self.button_play.SetBitmap(wx.Bitmap("img/play.jpeg", wx.BITMAP_TYPE_ANY))

    def Destroy(self):
        self.destroy_flag = True
        return super().Destroy()

    class Music():
        def __init__(self, file_name):
            pygame.mixer.init()
            pygame.mixer.music.load(file_name)
            self.length = mp3(file_name).info.length

        def start(self, loops=0, start=0):
            pygame.mixer.music.play(loops=loops, start=start)

        def stop(self):
            pygame.mixer.music.stop()

        def pause(self):
            pygame.mixer.music.pause()


