class MakePlayListDialog(MakePlayListDialogBase):
    def __init__(self, *args, **kwds):
        super().__init__(*args, **kwds)
        imageList = wx.ImageList(16, 16)
        idx1 = imageList.Add(wx.ArtProvider.GetBitmap(wx.ART_FOLDER, wx.ART_OTHER, (16, 16)))
        idx2 = imageList.Add((wx.ArtProvider.GetBitmap(wx.ART_NEW, wx.ART_OTHER, (16, 16))))
        self.folder_tree.AssignImageList(imageList)
        tree_dict = {}
        for full_path in gl.glob(r"D:\OneDrive - SatoshiOhtomo\05_MUSIC\**\*mp3", recursive=True):
            if os.path.isdir(full_path):
                continue
            key = ""
            item = None
            counter = 0
            for d in full_path.split(os.sep):
                key = os.path.join(key, d) if counter > 0 else "{}{}".format(d, os.sep)
                if key in tree_dict:
                    item = tree_dict[key]
                else:
                    if counter == 0:
                        item = self.folder_tree.AddRoot(d, idx1, -1, None)
                    else:
                        if os.path.isdir(key):
                            item = self.folder_tree.AppendItem(item, d, idx1, -1, None)
                        else:
                            item = self.folder_tree.AppendItem(item, d, idx2, -1, None)
                counter += 1
                tree_dict[key] = item


